  init(templatesDir: string): void {
    if (!fs.existsSync(templatesDir)) return;

    // Load partials
    const partialsDir = path.join(templatesDir, 'partials');
    if (fs.existsSync(partialsDir)) {
      const files = fs.readdirSync(partialsDir);
      for (const file of files) {
        if (file.endsWith('.hbs')) {
          const name = path.basename(file, '.hbs');
          const content = fs.readFileSync(path.join(partialsDir, file), 'utf-8');
          Handlebars.registerPartial(name, content);
        }
      }
    }

    // Load layouts
    const layoutsDir = path.join(templatesDir, 'layouts');
    if (fs.existsSync(layoutsDir)) {
      const files = fs.readdirSync(layoutsDir);
      for (const file of files) {
        if (file.endsWith('.hbs')) {
          const name = path.basename(file, '.hbs');
          const content = fs.readFileSync(path.join(layoutsDir, file), 'utf-8');
          this.layouts.set(name, Handlebars.compile(content));
        }
      }
    }

    // Load page templates
    const files = fs.readdirSync(templatesDir);
    for (const file of files) {
      if (file.endsWith('.hbs')) {
        const name = path.basename(file, '.hbs');
        const content = fs.readFileSync(path.join(templatesDir, file), 'utf-8');
        this.templates.set(name, Handlebars.compile(content));
      }
    }
  }

  renderPage(page: Page): string {
    // Get template name from page frontmatter
    const templateName = page.frontmatter.template;
    const template = templateName ? this.templates.get(templateName) : undefined;

    // If no custom template or not found, use default
    const compiledTemplate = template || this.pageTemplate;

    // Render page content
    const { title, date, tags } = page.frontmatter;
    const pageHtml = compiledTemplate({
      title,
      date: date || null,
      tags: tags || null,
      body: page.html,
    });

    // Apply layout
    const layoutName = page.frontmatter.layout;
    const layout = layoutName ? this.layouts.get(layoutName) : undefined;
    const compiledLayout = layout || this.layoutTemplate;

    return compiledLayout({
      title,
      date: date || null,
      tags: tags || null,
      body: pageHtml,
      content: page.html,
    });
  }

  renderIndex(pages: Page[]): string {
    // Similar - use default index template
    const items = pages.map(p => ({
      title: p.frontmatter.title,
      date: p.frontmatter.date || null,
      tags: p.frontmatter.tags || null,
      slug: p.slug,
    }));

    return this.indexTemplate({ pages: items });
  }
}
