Let me look at test 8 more carefully:

```javascript
it('sends reload message on content file change', async () => {
    createContentFile('alpha.md', `---\ntitle: Alpha\n---\nAlpha content`);
    await startServer();

    const addr = instance!.server.address();
    const port = typeof addr === 'object' && addr ? addr.port : 0;

    const ws = new WebSocket(`ws://localhost:${port}/__ssg_livereload`);
