        // ignore
    }
    instance = null;
}
```

And `close()` calls `wss.close(() => { server.close(() => resolve()); })`. The `wss.close()` callback is called after all WebSocket connections are closed. But before the callback runs, we also call `client.terminate()` for all clients.

